def transform(g):
    g=[row[:] for row in g]; h,w=len(g),len(g[0])
    for c in range(w):
        if g[h-1][c]==0: continue
        prev=-1
        for r in range(h):
            v=g[r][c]
            if v:
                for rr in range(prev+1,r): g[rr][c]=v
                prev=r
    return g
